  TEMPLATE_DOC_ID: 'PASTE_TEMPLATE_DOC_ID_HERE',
  // ID from the folder's URL: drive.google.com/drive/folders/<THIS PART>
  OUTPUT_FOLDER_ID: 'PASTE_OUTPUT_FOLDER_ID_HERE',
  // Tab holding the customers. Row 1 must be headers.
  SHEET_NAME: 'Customers',
  // How {{due_date}} appears in the letter, e.g. "14 November 2026".
  DATE_FORMAT: 'd MMMM yyyy',
  // File name for each letter; {{placeholders}} are filled from the row.
  FILE_NAME: 'Service reminder - {{first_name}} - {{bike}}',
  // Placeholders that must be present in the sheet headers and filled per row.
  FIELDS: ['first_name', 'bike', 'due_date'],
  // Columns the script writes to (added automatically if missing).
  URL_COLUMN: 'doc_url',
  STATUS_COLUMN: 'status',
  // Stop well before the 6-minute execution limit.
  TIME_BUDGET_MS: 4.5 * 60 * 1000,
};

const RESUME_HANDLER = 'resumeLetters';

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Service letters')
    .addItem('Generate test letter (first pending row)', 'generateTestLetter')
    .addItem('Generate all letters', 'generateAllLetters')
