}

/** Called by the time-based trigger when a previous run ran out of time. */
function resumeLetters() {
  run_({});
}

function clearStatus() {
  const ui = SpreadsheetApp.getUi();
  const answer = ui.alert(
    'Clear doc_url and status for every row?',
    'Letters already in Drive are not deleted; the next run will create new copies.',
    ui.ButtonSet.OK_CANCEL);
  if (answer !== ui.Button.OK) return;

  const sheet = getSheet_();
  const cols = ensureOutputColumns_(sheet);
  const rows = sheet.getLastRow() - 1;
  if (rows > 0) {
