}

function run_(options) {
  const lock = LockService.getDocumentLock();
  if (!lock.tryLock(5000)) {
    return { busy: true };
  }
  try {
    deleteResumeTriggers_();
    const started = Date.now();
    const sheet = getSheet_();
    const tz = sheet.getParent().getSpreadsheetTimeZone();
    const template = DriveApp.getFileById(CONFIG.TEMPLATE_DOC_ID);
    const folder = DriveApp.getFolderById(CONFIG.OUTPUT_FOLDER_ID);
    const cols = ensureOutputColumns_(sheet);

    const values = sheet.getDataRange().getValues();
    const display = sheet.getDataRange().getDisplayValues();
    const result = { created: 0, failed: 0, remaining: 0 };

    for (let r = 1; r < values.length; r++) {
      const row = values[r];
      if (row.every(function (v) { return v === ''; })) continue;
      if (row[cols.url]) continue;

      const hitLimit = options.limit && result.created + result.failed >= options.limit;
      if (hitLimit || Date.now() - started > CONFIG.TIME_BUDGET_MS) {
        result.remaining++;
