      try {
        const data = rowData_(row, display[r], cols.fields, tz);
        const file = createLetter_(template, folder, data);
        sheet.getRange(r + 1, cols.url + 1).setValue(file.getUrl());
        statusCell.setValue('Created ' + Utilities.formatDate(new Date(), tz, 'yyyy-MM-dd HH:mm'));
