    if (raw instanceof Date) {
      value = Utilities.formatDate(raw, tz, CONFIG.DATE_FORMAT);
    } else {
      value = String(displayRow[fieldCols[field]]).trim();
    }
    if (!value) throw new Error('missing ' + field);
    data[field] = value;
