  return data;
}

function createLetter_(template, folder, data) {
  const name = fillPlaceholders_(CONFIG.FILE_NAME, data);
  const copy = template.makeCopy(name, folder);
  const doc = DocumentApp.openById(copy.getId());

  const sections = [doc.getBody(), doc.getHeader(), doc.getFooter()];
  sections.forEach(function (section) {
    if (!section) return;
    Object.keys(data).forEach(function (field) {
      // replaceText takes a regex pattern; the replacement is literal except
      // for "\" and "$", which are escaped so values like "$50" survive.
      const replacement = data[field].replace(/\\/g, '\\\\').replace(/\$/g, '\\$');
      section.replaceText('\\{\\{\\s*' + field + '\\s*\\}\\}', replacement);
    });
  });

  doc.saveAndClose();
  return copy;
}

function fillPlaceholders_(text, data) {
  return text.replace(/\{\{\s*(\w+)\s*\}\}/g, function (match, field) {
    return field in data ? data[field] : match;
  });
}

function getSheet_() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(CONFIG.SHEET_NAME);
  if (!sheet) throw new Error('No tab named "' + CONFIG.SHEET_NAME + '". Update CONFIG.SHEET_NAME.');
  return sheet;
}

/** Finds the placeholder columns and adds doc_url/status columns if needed. */
function ensureOutputColumns_(sheet) {
  let headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0]
    .map(function (h) { return String(h).trim().toLowerCase(); });

  [CONFIG.URL_COLUMN, CONFIG.STATUS_COLUMN].forEach(function (name) {
    if (headers.indexOf(name) === -1) {
      sheet.getRange(1, headers.length + 1).setValue(name);
      headers.push(name);
    }
  });

  const fields = {};
  const missing = [];
  CONFIG.FIELDS.forEach(function (field) {
    const i = headers.indexOf(field);
    if (i === -1) missing.push(field);
    fields[field] = i;
  });
  if (missing.length) {
    throw new Error('Sheet is missing header(s): ' + missing.join(', '));
  }

  return {
    fields: fields,
    url: headers.indexOf(CONFIG.URL_COLUMN),
    status: headers.indexOf(CONFIG.STATUS_COLUMN),
  };
}

function deleteResumeTriggers_() {
  ScriptApp.getProjectTriggers().forEach(function (t) {
    if (t.getHandlerFunction() === RESUME_HANDLER) ScriptApp.deleteTrigger(t);
  });
}

function summary_(result) {
  if (result.busy) return 'A run is already in progress. Try again in a few minutes.';
  let msg = 'Created ' + result.created + ' letter(s).';
  if (result.failed) msg += '\n' + result.failed + ' row(s) failed - see the status column.';
  if (result.resumed) {
    msg += '\n' + result.remaining + ' row(s) left; the script will continue automatically in about a minute.';
  } else if (result.remaining) {
    msg += '\n' + result.remaining + ' row(s) still pending.';
  }
  return msg;
}

