       [row.get('doc_id')].concat(String(row.get('previous_doc_ids') || '').split(','))
         .forEach(function (id) { id = String(id || '').trim(); if (id) { known[id] = row.rowNumber; } });
     });
     var files = DriveApp.getFolderById(getSetting_('OUTPUT_FOLDER_ID')).getFiles();
     var names = {}, stray = [], total = 0;
     while (files.hasNext()) {
       var f = files.next(); total++;
       var n = f.getName().replace(FAILED_PREFIX, '');
       (names[n] = names[n] || []).push(f.getId());
       if (!known[f.getId()]) { stray.push(f.getName() + '  ' + f.getId()); }
     }
     Logger.log('Files in folder: ' + total + '. Not linked to any row: ' + stray.length + '\n' + stray.join('\n'));
     Object.keys(names).forEach(function (n) {
       if (names[n].length > 1) { Logger.log('Same name x' + names[n].length + ': ' + n); }
     });
   }
